INSERT INTO golden_qc_variant(variant_id,episode_id,name,payload) VALUES ('QC-V02','EP-DEMO-001','结算清单多出EMR不存在的ENBD操作','{"variantId": "QC-V02", "name": "结算清单多出EMR不存在的ENBD操作", "baseEpisodeId": "EP-DEMO-001", "applyTo": "医保结算清单", "mutation": [{"op": "add", "path": "/procedures/others/-", "value": {"code": "51.8600x002", "name": "内镜下鼻胆管引流术（ENBD）", "source": "仅注入结算清单"}}], "expected": [{"code": "SETTLEMENT_EMR_PROCEDURE_MISMATCH", "severity": "error", "action": "退回核实"}, {"code": "DIP_COUNTERFACTUAL_CHANGED", "severity": "warning", "message": "若错误数据直接进入DIP规则，将改变规则表命中；因此必须先做跨源一致性质控。"}], "counterfactual": {"correctRuleMatch": {"classification": "BX", "sequence": 1029}, "withInjectedRelatedProcedure": {"classification": "BX", "sequence": 1025}, "purpose": "验证‘编码/操作错误会改变DIP分组’这一条链路"}}'::jsonb) ON CONFLICT (variant_id) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO golden_qc_variant(variant_id,episode_id,name,payload) VALUES ('QC-V03','EP-DEMO-001','费用明细合计与清单总额不一致','{"variantId": "QC-V03", "name": "费用明细合计与清单总额不一致", "baseEpisodeId": "EP-DEMO-001", "applyTo": "医保结算清单", "mutation": [{"op": "replace", "path": "/fees/rows/5/amount", "value": 5801}], "expected": [{"code": "FEE_TOTAL_MISMATCH", "severity": "error", "action": "阻断申报"}, {"code": "PAYMENT_TOTAL_CHECK", "severity": "warning", "action": "核对支付结果"}]}'::jsonb) ON CONFLICT (variant_id) DO UPDATE SET payload=EXCLUDED.payload;
